#include <string>
#include <vector>
#include <unordered_map>

bool befittingBrackets(std::string str) {
  std::vector<char> stack;
  std::unordered_map<char, char> symbols { 
    { '{', '}' },
    { '[', ']' },
    { '(', ')' }
  };
  for (char ch : str) {
    if (symbols.count(ch) > 0) {
      stack.push_back(symbols[ch]);
    } else {
      if (stack.size() > 0 && stack[stack.size() - 1] == ch) {
        stack.pop_back();
      } else {
        return false;
      }
    }
  }
  return stack.size() == 0;
}
```

- n = length of string
- Time: O(n)
- Space: O(n)
